window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bea331d4bc9c556c"]={"versions": [{"id": "FIG-bea331d4bc9c556c", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Algorithmus bzw. Subdiagramms <code>E2E_P01_getDataIDCRC(DataID, DataIDMode)</code>. Das Diagramm beschreibt einen deterministischen Berechnungsablauf innerhalb der E2E-Bibliothek (AUTOSAR PRS E2E Protocol), der direkt durch die Schutz- und Prüffunktionen <code>E2E_P01Protect()</code> sowie <code>E2E_P01Check()</code> zur E2E-Profil-1-Prüfsummeninitialisierung genutzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsparameter / Kontext:</strong></li>\n<li><code>DataID</code>: Bezeichner bzw. Konfigurationswert der Datenidentifikation (16 Bit).</li>\n<li><code>DataIDMode</code>: Konfigurationsmodus vom Aufzählungstyp für die Berücksichtigung der Data-ID.</li>\n<li><code>State-&gt;Counter</code>: Zustandsparameter (Sequenzzähler) der E2E-Zustandsstruktur.</li>\n<li><strong>Verwendete Routinen / Schnittstellen:</strong></li>\n<li><code>Crc_CalculateCRC8(Crc_DataPtr, Crc_Length, Crc_StartValue8, Crc_IsFirstCall)</code>: Funktion der CRC-Bibliothek zur 8-Bit-CRC-Berechnung.</li>\n<li><strong>Knoten und Kontrollstrukturen:</strong></li>\n<li>Initialer Startknoten <code>E2E_P01_getDataIDCRC(DataID, DataIDMode)</code>.</li>\n<li>Verzweigungsknoten (Decision Nodes): <code>switch DataIDMode</code> mit vier Pfaden sowie Unterverzweigung <code>State-&gt;Counter % 2 == 0</code>.</li>\n<li>Aktionsknoten zur CRC-Berechnung.</li>\n<li>Zusammenführungsknoten (Merge Nodes).</li>\n<li>Endknoten <code>ActivityFinal</code>.</li>\n<li><strong>Modus-Konstanten / Guard-Bedingungen:</strong></li>\n<li><code>[case E2E_P01_DATAID_BOTH]</code></li>\n<li><code>[case E2E_P01_DATAID_LOW]</code></li>\n<li><code>[case E2E_P01_DATAID_ALT]</code> (mit Sub-Bedingungen <code>[TRUE]</code> und <code>[FALSE]</code>)</li>\n<li><code>[case E2E_P01_DATAID_NIBBLE]</code></li>\n<li><strong>Ergebnis / Rückgabewert:</strong></li>\n<li>Berechneter 8-Bit-Prüfwert <code>CRC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss startet am initialen Knoten und verzweigt über eine Fallunterscheidung (<code>switch DataIDMode</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_BOTH</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erster Schritt: <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (Berechnung über das Low-Byte von DataID mit Startwert <code>0xFF</code>).</li>\n<li>Zweiter Schritt: <code>CRC = Crc_CalculateCRC8(DataID&gt;&gt;8, 1, CRC, FALSE)</code> (Berechnung über das High-Byte von DataID mit dem Zwischenergebnis <code>CRC</code> als Startwert).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_LOW</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Einzelschritt: <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (nur Low-Byte von DataID).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_ALT</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verzweigung anhand der Parität des Zählers (<code>State-&gt;Counter % 2 == 0</code>):</li>\n<li>Wenn <code>[TRUE]</code> (gerader Zähler): <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (Low-Byte).</li>\n<li>Wenn <code>[FALSE]</code> (ungerader Zähler): <code>CRC = Crc_CalculateCRC8(DataID&gt;&gt;8, 1, 0xFF, FALSE)</code> (High-Byte).</li>\n<li>Die beiden Zweige werden über einen Merge-Knoten zusammengeführt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_NIBBLE</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erster Schritt: <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (Low-Byte von DataID).</li>\n<li>Zweiter Schritt: <code>CRC = Crc_CalculateCRC8(0, 1, CRC, FALSE)</code> (Berechnung über das Byte <code>0</code> mit dem vorherigen <code>CRC</code> als Startwert).</li>\n</ul>\n<p class=\"fig-p\">Alle vier Pfade münden in einen gemeinsamen Merge-Knoten und führen zum <code>ActivityFinal</code>-Knoten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Logik für E2E Profile 1:</strong></li>\n<li>Die Funktion muss die Data-ID zwingend gemäß dem konfigurierten <code>DataIDMode</code> in die Prüfsummenbildung einbinden.</li>\n<li>Der Parameter <code>Crc_IsFirstCall</code> wird bei allen Aufrufen explizit auf <code>FALSE</code> gesetzt.</li>\n<li>Die erste Iteration von <code>Crc_CalculateCRC8</code> wird stets mit dem Startwert <code>0xFF</code> aufgerufen. Da die CRC-Bibliotheksfunktion den übergebenen Startwert initial mit <code>0xFF</code> XOR-verknüpft, resultiert intern ein tatsächlicher Startwert von <code>0x00</code>.</li>\n<li>Bei zweistufigen Berechnungen (<code>E2E_P01_DATAID_BOTH</code> und <code>E2E_P01_DATAID_NIBBLE</code>) dient das Rückgabe-CRC des ersten Aufrufs unverändert als Startwert für den zweiten Aufruf. Ein manuelles Nach-XORen entfällt, da das abschließende XOR der ersten Funktion und das eingangsseitige XOR der nachfolgenden Funktion sich gegenseitig aufheben (<code>CRC ^ 0xFF ^ 0xFF = CRC</code>).</li>\n<li>Im Modus <code>E2E_P01_DATAID_ALT</code> hängt die Einbindung von High- bzw. Low-Byte strikt vom aktuellen Zustand des E2E-Counters ab.</li>\n</ul>"}, {"id": "FIG-6ef7101f479df4f7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Algorithmus bzw. Subdiagramms <code>E2E_P01_getDataIDCRC(DataID, DataIDMode)</code>. Das Diagramm beschreibt einen deterministischen Berechnungsablauf innerhalb der E2E-Bibliothek (AUTOSAR PRS E2E Protocol), der direkt durch die Schutz- und Prüffunktionen <code>E2E_P01Protect()</code> sowie <code>E2E_P01Check()</code> zur E2E-Profil-1-Prüfsummeninitialisierung genutzt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsparameter / Kontext:</strong></li>\n<li><code>DataID</code>: Bezeichner bzw. Konfigurationswert der Datenidentifikation (16 Bit).</li>\n<li><code>DataIDMode</code>: Konfigurationsmodus vom Aufzählungstyp für die Berücksichtigung der Data-ID.</li>\n<li><code>State-&gt;Counter</code>: Zustandsparameter (Sequenzzähler) der E2E-Zustandsstruktur.</li>\n<li><strong>Verwendete Routinen / Schnittstellen:</strong></li>\n<li><code>Crc_CalculateCRC8(Crc_DataPtr, Crc_Length, Crc_StartValue8, Crc_IsFirstCall)</code>: Funktion der CRC-Bibliothek zur 8-Bit-CRC-Berechnung.</li>\n<li><strong>Knoten und Kontrollstrukturen:</strong></li>\n<li>Initialer Startknoten <code>E2E_P01_getDataIDCRC(DataID, DataIDMode)</code>.</li>\n<li>Verzweigungsknoten (Decision Nodes): <code>switch DataIDMode</code> mit vier Pfaden sowie Unterverzweigung <code>State-&gt;Counter % 2 == 0</code>.</li>\n<li>Aktionsknoten zur CRC-Berechnung.</li>\n<li>Zusammenführungsknoten (Merge Nodes).</li>\n<li>Endknoten <code>ActivityFinal</code>.</li>\n<li><strong>Modus-Konstanten / Guard-Bedingungen:</strong></li>\n<li><code>[case E2E_P01_DATAID_BOTH]</code></li>\n<li><code>[case E2E_P01_DATAID_LOW]</code></li>\n<li><code>[case E2E_P01_DATAID_ALT]</code> (mit Sub-Bedingungen <code>[TRUE]</code> und <code>[FALSE]</code>)</li>\n<li><code>[case E2E_P01_DATAID_NIBBLE]</code></li>\n<li><strong>Ergebnis / Rückgabewert:</strong></li>\n<li>Berechneter 8-Bit-Prüfwert <code>CRC</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss startet am initialen Knoten und verzweigt über eine Fallunterscheidung (<code>switch DataIDMode</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_BOTH</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erster Schritt: <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (Berechnung über das Low-Byte von DataID mit Startwert <code>0xFF</code>).</li>\n<li>Zweiter Schritt: <code>CRC = Crc_CalculateCRC8(DataID&gt;&gt;8, 1, CRC, FALSE)</code> (Berechnung über das High-Byte von DataID mit dem Zwischenergebnis <code>CRC</code> als Startwert).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_LOW</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Einzelschritt: <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (nur Low-Byte von DataID).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_ALT</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verzweigung anhand der Parität des Zählers (<code>State-&gt;Counter % 2 == 0</code>):</li>\n<li>Wenn <code>[TRUE]</code> (gerader Zähler): <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (Low-Byte).</li>\n<li>Wenn <code>[FALSE]</code> (ungerader Zähler): <code>CRC = Crc_CalculateCRC8(DataID&gt;&gt;8, 1, 0xFF, FALSE)</code> (High-Byte).</li>\n<li>Die beiden Zweige werden über einen Merge-Knoten zusammengeführt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Pfad <code>E2E_P01_DATAID_NIBBLE</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erster Schritt: <code>CRC = Crc_CalculateCRC8(DataID, 1, 0xFF, FALSE)</code> (Low-Byte von DataID).</li>\n<li>Zweiter Schritt: <code>CRC = Crc_CalculateCRC8(0, 1, CRC, FALSE)</code> (Berechnung über das Byte <code>0</code> mit dem vorherigen <code>CRC</code> als Startwert).</li>\n</ul>\n<p class=\"fig-p\">Alle vier Pfade münden in einen gemeinsamen Merge-Knoten und führen zum <code>ActivityFinal</code>-Knoten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Logik für E2E Profile 1:</strong></li>\n<li>Die Funktion muss die Data-ID zwingend gemäß dem konfigurierten <code>DataIDMode</code> in die Prüfsummenbildung einbinden.</li>\n<li>Der Parameter <code>Crc_IsFirstCall</code> wird bei allen Aufrufen explizit auf <code>FALSE</code> gesetzt.</li>\n<li>Die erste Iteration von <code>Crc_CalculateCRC8</code> wird stets mit dem Startwert <code>0xFF</code> aufgerufen. Da die CRC-Bibliotheksfunktion den übergebenen Startwert initial mit <code>0xFF</code> XOR-verknüpft, resultiert intern ein tatsächlicher Startwert von <code>0x00</code>.</li>\n<li>Bei zweistufigen Berechnungen (<code>E2E_P01_DATAID_BOTH</code> und <code>E2E_P01_DATAID_NIBBLE</code>) dient das Rückgabe-CRC des ersten Aufrufs unverändert als Startwert für den zweiten Aufruf. Ein manuelles Nach-XORen entfällt, da das abschließende XOR der ersten Funktion und das eingangsseitige XOR der nachfolgenden Funktion sich gegenseitig aufheben (<code>CRC ^ 0xFF ^ 0xFF = CRC</code>).</li>\n<li>Im Modus <code>E2E_P01_DATAID_ALT</code> hängt die Einbindung von High- bzw. Low-Byte strikt vom aktuellen Zustand des E2E-Counters ab.</li>\n</ul>"}], "trans": [{"from": "FIG-bea331d4bc9c556c", "to": "FIG-6ef7101f479df4f7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
